#include <iostream>
#include <memory>
#include <vector>

static int g_destroyed = 0;

// The solution's Node must match this layout exactly.
struct Node
{
    int value = 0;
    std::shared_ptr<Node> next;
    std::weak_ptr<Node> prev;
    ~Node();
};

Node::~Node() { g_destroyed++; }

std::shared_ptr<Node> BuildChain(const std::vector<int>& values);

int main()
{
    int n;
    while (std::cin >> n)
    {
        std::vector<int> values(n);
        for (int i = 0; i < n; i++)
        {
            std::cin >> values[i];
        }

        g_destroyed = 0;
        {
            std::shared_ptr<Node> head = BuildChain(values);

            std::cout << "forward:";
            for (Node* p = head.get(); p; p = p->next.get())
            {
                std::cout << " " << p->value;
            }
            std::cout << "\n";

            // Find the tail without keeping extra owners alive afterwards.
            Node* last = head.get();
            while (last && last->next) { last = last->next.get(); }

            std::cout << "backward:";
            Node* cursor = last;
            while (cursor)
            {
                std::cout << " " << cursor->value;
                std::shared_ptr<Node> prev = cursor->prev.lock();
                cursor = prev.get();
            }
            std::cout << "\n";

            std::cout << "head use_count: " << (head ? head.use_count() : 0) << "\n";
        }
        std::cout << "destroyed: " << g_destroyed << " of " << n << "\n";
    }
    return 0;
}

