"""Random chains of 0 to 8 values."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 8)
    values = [rng.randint(-20, 20) for _ in range(n)]
    return {"name": "a chain of %d nodes #%d" % (n, index),
            "stdin": "%d\n%s\n" % (n, " ".join(map(str, values)))}
